def _get_line(self):

    line = self.readline()
    if not line:
        raise self.abort('socket error: EOF')

    # Protocol mandates all lines terminated by CRLF
    if not line.endswith(b'\r\n'):
        raise self.abort('socket error: unterminated line: %r' % line)

    line = line[:-2]
    if __debug__:
        if self.debug >= 4:
            self._mesg('< %r' % line)
        else:
            self._log('< %r' % line)
